CREATE FUNCTION [dbo].[MOG_EN]    (@FORMS___F_MENU_ANBAR_TARAZ___DT2 bigint)      RETURNS TABLE     AS    RETURN ( SELECT     dbo.INVO_LST.ANBARF, dbo.INVO_LST.CODE, SUM(dbo.INVO_LST.MEGHk - dbo.INVO_LST.MEGH_MAR) AS MEG, SUM(dbo.INVO_LST.MABL_K )  AS SumOfMABL_K     FROM         dbo.INVO_LST INNER JOIN  dbo.HEAD_LST ON dbo.INVO_LST.NUMBER = dbo.HEAD_LST.NUMBER AND dbo.INVO_LST.TAG = dbo.HEAD_LST.TAG     WHERE     (dbo.INVO_LST.TAG = 5) AND (dbo.HEAD_LST.DATE_N <= @FORMS___F_MENU_ANBAR_TARAZ___DT2)     GROUP BY dbo.INVO_LST.ANBARF, dbo.INVO_LST.CODE     union     SELECT     dbo.INVO_LST.ANBAR, dbo.INVO_LST.CODE, SUM(dbo.INVO_LST.MEGHk - dbo.INVO_LST.MEGH_MAR) AS MEG, SUM(dbo.INVO_LST.MABL_k - dbo.INVO_LST.MEGH_MAR * dbo.INVO_LST.AVRAGE)  AS SumOfMABL_K     FROM         dbo.INVO_LST INNER JOIN  dbo.HEAD_LST ON dbo.INVO_LST.NUMBER = dbo.HEAD_LST.NUMBER AND dbo.INVO_LST.TAG = dbo.HEAD_LST.TAG     WHERE     ((dbo.INVO_LST.TAG = 1)   OR  (dbo.INVO_LST.TAG = 7) OR  (dbo.INVO_LST.TAG = 9)) AND (dbo.HEAD_LST.DATE_N <= @FORMS___F_MENU_ANBAR_TARAZ___DT2)     GROUP BY dbo.INVO_LST.ANBAR, dbo.INVO_LST.CODE     union     SELECT     dbo.INVO_LST.ANBAR, dbo.INVO_LST.CODE, SUM(dbo.INVO_LST.MEGHk) AS MEG, SUM(dbo.INVO_LST.AVRAGE * dbo.INVO_LST.MEGHk) AS SumOfMABL_K    FROM         dbo.INVO_LST INNER JOIN                 dbo.HEAD_LST ON dbo.INVO_LST.NUMBER = dbo.HEAD_LST.NUMBER AND dbo.INVO_LST.TAG = dbo.HEAD_LST.TAG     WHERE     (dbo.INVO_LST.TAG = 22  OR dbo.INVO_LST.TAG =24 ) AND (dbo.HEAD_LST.DATE_N <= @FORMS___F_MENU_ANBAR_TARAZ___DT2)     GROUP BY dbo.INVO_LST.ANBAR, dbo.INVO_LST.CODE     union  SELECT     dbo.ANBGRD_HEAD.GRD_ANBAR AS anbar, dbo.ANBGRD_LST.CODE, SUM((dbo.ANBGRD_LST.MOG - dbo.ANBGRD_LST.NUM3) * - 1) AS MEG,  SUM(dbo.ANBGRD_LST.mabl * ((dbo.ANBGRD_LST.MOG - dbo.ANBGRD_LST.NUM3) * -1)) As MABLK     FROM         dbo.ANBGRD_LST INNER JOIN  dbo.ANBGRD_HEAD ON dbo.ANBGRD_LST.GRD_NUM = dbo.ANBGRD_HEAD.GRD_NUM     WHERE     ((dbo.ANBGRD_LST.MOG - dbo.ANBGRD_LST.NUM3) * - 1 > 0) AND (NOT (dbo.ANBGRD_HEAD.N_S IS NULL)) AND (dbo.ANBGRD_HEAD.GRD_DATE <= @FORMS___F_MENU_ANBAR_TARAZ___DT2)     GROUP BY dbo.ANBGRD_HEAD.GRD_ANBAR, dbo.ANBGRD_LST.CODE)
